import Foundation

/// Foundation-only Console logic; compiled into the unit-test bundle together with OrbitInspectDecode.swift.

// MARK: - Level

public enum ConLevel: String, CaseIterable, Equatable, Sendable {
    case log, info, warn, error, debug, trace
    case dir, dirxml, table
    case group, groupCollapsed, groupEnd
    case count, time
    case assert_
    case clear
    // Synthetic levels generated by Swift model
    case exception, unhandledRejection, resourceError, cspViolation
    case navigation   // "Navigated to <url>" separator
    case result       // REPL result echo
    case command      // REPL input echo
}

public extension ConLevel {
    var isError: Bool {
        self == .error || self == .exception || self == .unhandledRejection || self == .assert_
    }
    var isWarn: Bool  { self == .warn }
    var isInfo: Bool  { self == .info }
    var isVerbose: Bool {
        self == .debug || self == .trace || self == .resourceError || self == .cspViolation
    }

    var symbol: String? {
        switch self {
        case .error, .exception, .unhandledRejection, .assert_: return "xmark.circle.fill"
        case .warn:           return "exclamationmark.triangle.fill"
        case .info:           return "info.circle.fill"
        case .resourceError:  return "xmark.octagon.fill"
        case .cspViolation:   return "lock.trianglebadge.exclamationmark.fill"
        case .navigation:     return "arrow.right.circle"
        case .command:        return "chevron.right"
        default:              return nil
        }
    }

    enum Background { case none, info, warn, error }
    var background: Background {
        if isError          { return .error }
        if isWarn           { return .warn }
        if self == .info    { return .info }
        return .none
    }
}

// MARK: - Filter level

public enum ConFilterLevel: String, CaseIterable, Sendable, Hashable {
    case all, errors, warnings, info, logs, verbose

    public var title: String {
        switch self {
        case .all:      return "All"
        case .errors:   return "Errors"
        case .warnings: return "Warnings"
        case .info:     return "Info"
        case .logs:     return "Logs"
        case .verbose:  return "Verbose"
        }
    }

    public func matches(_ level: ConLevel) -> Bool {
        switch self {
        case .all:      return level != .navigation
        case .errors:   return level.isError
        case .warnings: return level.isWarn
        case .info:     return level.isInfo
        case .logs:
            return level == .log || level == .dir || level == .dirxml
                || level == .table || level == .count || level == .time
                || level == .result || level == .command
        case .verbose:
            return level.isVerbose || level == .trace || level == .debug
        }
    }
}

// MARK: - Stack frame

public struct ConStackFrame: Equatable, Hashable, Sendable {
    public var function: String
    public var url: String
    public var line: Int
    public var column: Int

    public init(function: String, url: String, line: Int, column: Int) {
        self.function = function
        self.url = url
        self.line = line
        self.column = column
    }

    public var isAnonymous: Bool {
        function.isEmpty || function == "anonymous" || function == "<anonymous>"
    }
    public var displayName: String { isAnonymous ? "(anonymous)" : function }

    /// Short right-column label, e.g. "App.jsx:42".
    public var shortURL: String {
        guard !url.isEmpty else { return "" }
        let noQuery = url.components(separatedBy: "?").first ?? url
        let file = noQuery.components(separatedBy: "/").last ?? noQuery
        return line > 0 ? "\(file):\(line)" : file
    }
}

// MARK: - Format specifiers

public enum ConFormatSpec: String, Equatable, Sendable {
    case string_ = "s"
    case decimal = "d"
    case integer = "i"
    case float = "f"
    case object = "o"
    case objectXML = "O"
    case css = "c"
}

public enum ConFormatRun: Equatable, Sendable {
    case text(String)
    case substitution(argIndex: Int, spec: ConFormatSpec)
    case styledText(String, ConCSSStyle)
}

public struct ConCSSStyle: Equatable, Sendable {
    public var color: String?
    public var backgroundColor: String?
    public var fontWeight: String?
    public var fontSize: String?
    public var fontStyle: String?
    public var textDecoration: String?

    public static let empty = ConCSSStyle()

    public var isEmpty: Bool {
        color == nil && backgroundColor == nil && fontWeight == nil
            && fontSize == nil && fontStyle == nil && textDecoration == nil
    }
    public var isBold: Bool { fontWeight == "bold" || (fontWeight.map { $0.hasPrefix("7") } ?? false) }
    public var isItalic: Bool { fontStyle == "italic" }
}

// MARK: - History

public struct ConHistory: Equatable, Sendable {
    public var entries: [String] = []
    public var cursor: Int = 0

    public init() { cursor = 0 }

    public mutating func push(_ text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        entries.removeAll { $0 == trimmed }
        entries.append(trimmed)
        if entries.count > 200 { entries.removeFirst(entries.count - 200) }
        cursor = entries.count
    }

    public mutating func up() -> String? {
        guard !entries.isEmpty else { return nil }
        cursor = max(0, cursor - 1)
        return entries.indices.contains(cursor) ? entries[cursor] : nil
    }

    public mutating func down() -> String? {
        if cursor >= entries.count { return nil }
        cursor += 1
        if cursor >= entries.count { return "" }
        return entries[cursor]
    }

    public mutating func resetCursor() { cursor = entries.count }
}

// MARK: - Filter query

public struct ConFilterQuery: Equatable, Sendable {
    public var text: String = ""
    public var isRegex: Bool = false
    public var isNegated: Bool = false
    public var urlFilter: String? = nil

    public static let empty = ConFilterQuery()
    public var isEmpty: Bool { text.isEmpty && urlFilter == nil }
}

// MARK: - Serialized JS value (Foundation-only, test-friendly)

public enum ConSerializedValue: Equatable, Hashable, Sendable {
    case string_(String)
    case number(Double)
    case numberSpecial(String)
    case boolean(Bool)
    case null_
    case undefined_
    case bigint(String)
    case symbol(String)
    case ref(id: Int, preview: String, cls: String, length: Int?)
    case function_(id: Int, preview: String)
    case domNode(id: Int, nodeId: Int, preview: String)
    case error_(id: Int, preview: String, stack: String)
    case date_(id: Int, preview: String)
    case regexp(id: Int, preview: String)

    public var preview: String {
        switch self {
        case .string_(let s):       return "\"\(s.prefix(400))\""
        case .number(let n):        return ConValueFormat.number(n)
        case .numberSpecial(let s): return s
        case .boolean(let b):       return b ? "true" : "false"
        case .null_:                return "null"
        case .undefined_:           return "undefined"
        case .bigint(let s):        return s
        case .symbol(let s):        return s
        case .ref(_, let p, _, _):  return p
        case .function_(_, let p):  return p
        case .domNode(_, _, let p): return p
        case .error_(_, let p, _):  return p
        case .date_(_, let p):      return p
        case .regexp(_, let p):     return p
        }
    }

    public var plainText: String {
        switch self {
        case .string_(let s):       return s
        case .number(let n):        return ConValueFormat.number(n)
        case .numberSpecial(let s): return s
        case .boolean(let b):       return b ? "true" : "false"
        case .null_:                return "null"
        case .undefined_:           return "undefined"
        case .bigint(let s):        return s
        case .symbol(let s):        return s
        default:                    return preview
        }
    }

    public var registryId: Int? {
        switch self {
        case .ref(let id, _, _, _):    return id
        case .function_(let id, _):    return id
        case .domNode(let id, _, _):   return id
        case .error_(let id, _, _):    return id
        case .date_(let id, _):        return id
        case .regexp(let id, _):       return id
        default:                       return nil
        }
    }

    public var isExpandable: Bool { registryId != nil }

    public static func decode(_ dict: [String: Any]) -> ConSerializedValue {
        let k = dict["k"] as? String ?? "u"
        switch k {
        case "s":
            return .string_(dict["v"] as? String ?? "")
        case "n":
            if let s = dict["s"] as? String { return .numberSpecial(s) }
            return .number(OrbitInspectDecode.number(dict, "v") ?? 0)
        case "b":
            return .boolean(OrbitInspectDecode.bool(dict, "v"))
        case "nu":   return .null_
        case "u":    return .undefined_
        case "bi":   return .bigint(dict["v"] as? String ?? "")
        case "sym":  return .symbol(dict["v"] as? String ?? "Symbol()")
        case "fn":
            return .function_(
                id: OrbitInspectDecode.integer(dict, "id"),
                preview: dict["preview"] as? String ?? "ƒ ()"
            )
        case "dn":
            return .domNode(
                id: OrbitInspectDecode.integer(dict, "id"),
                nodeId: OrbitInspectDecode.integer(dict, "nid"),
                preview: dict["preview"] as? String ?? "<element>"
            )
        case "err":
            return .error_(
                id: OrbitInspectDecode.integer(dict, "id"),
                preview: dict["preview"] as? String ?? "Error",
                stack: dict["stack"] as? String ?? ""
            )
        case "date":
            return .date_(
                id: OrbitInspectDecode.integer(dict, "id"),
                preview: dict["preview"] as? String ?? ""
            )
        case "re":
            return .regexp(
                id: OrbitInspectDecode.integer(dict, "id"),
                preview: dict["preview"] as? String ?? ""
            )
        case "ref":
            let len: Int? = OrbitInspectDecode.integer(dict["len"])
            return .ref(
                id: OrbitInspectDecode.integer(dict, "id"),
                preview: dict["preview"] as? String ?? "{…}",
                cls: dict["cls"] as? String ?? "Object",
                length: len
            )
        default:
            return .undefined_
        }
    }
}

// MARK: - Property descriptor

public struct ConPropDescriptor: Equatable, Sendable, Identifiable {
    public var id: String { name }
    public var name: String
    public var value: ConSerializedValue
    public var writable: Bool
    public var enumerable: Bool
    public var configurable: Bool
    public var isGetter: Bool

    public init(name: String, value: ConSerializedValue, writable: Bool,
                enumerable: Bool, configurable: Bool, isGetter: Bool) {
        self.name = name; self.value = value; self.writable = writable
        self.enumerable = enumerable; self.configurable = configurable; self.isGetter = isGetter
    }

    static func decode(_ dict: [String: Any]) -> ConPropDescriptor? {
        guard let name = dict["name"] as? String else { return nil }
        let valDict = dict["value"] as? [String: Any] ?? [:]
        return ConPropDescriptor(
            name: name,
            value: ConSerializedValue.decode(valDict),
            writable: OrbitInspectDecode.bool(dict, "writable"),
            enumerable: OrbitInspectDecode.bool(dict, "enumerable"),
            configurable: OrbitInspectDecode.bool(dict, "configurable"),
            isGetter: OrbitInspectDecode.bool(dict, "getter")
        )
    }
}

public enum ConExpandedState: Equatable, Sendable {
    case loading
    case loaded(own: [ConPropDescriptor], proto: ConSerializedValue?)
    case error(String)
}

// MARK: - Console entry

public struct ConEntry: Identifiable, Equatable, Sendable {
    public var id: String
    public var level: ConLevel
    public var args: [ConSerializedValue]
    public var stackFrames: [ConStackFrame]
    public var timestamp: Double
    public var groupDepth: Int
    public var isGroupStart: Bool
    public var isGroupEnd: Bool
    public var repeatCount: Int
    public var plainText: String
    public var tableRows: [[String: ConSerializedValue]]?
    public var sourceURL: String
    public var sourceLine: Int
    public var sourceColumn: Int
    public var formatString: String?

    /// Decodes one JS entry dict. `groupDepth` tracks group nesting (mutated in place).
    static func decode(_ dict: [String: Any], groupDepth: inout Int, pageCounter: Int) -> ConEntry? {
        let levelRaw = OrbitInspectDecode.string(dict, "level")
        let level: ConLevel
        switch levelRaw {
        case "log":              level = .log
        case "info":             level = .info
        case "warn":             level = .warn
        case "error":            level = .error
        case "debug":            level = .debug
        case "trace":            level = .trace
        case "dir":              level = .dir
        case "dirxml":           level = .dirxml
        case "table":            level = .table
        case "group":            level = .group
        case "groupCollapsed":   level = .groupCollapsed
        case "groupEnd":         level = .groupEnd
        case "count":            level = .count
        case "time":             level = .time
        case "assert":           level = .assert_
        case "clear":            level = .clear
        case "exception":        level = .exception
        case "unhandledrejection": level = .unhandledRejection
        case "resourceError":    level = .resourceError
        case "cspViolation":     level = .cspViolation
        default:                 return nil
        }

        let currentDepth = groupDepth
        let isStart = level == .group || level == .groupCollapsed
        let isEnd   = level == .groupEnd

        let argDicts = dict["args"] as? [[String: Any]] ?? []
        let args     = argDicts.map { ConSerializedValue.decode($0) }
        let frames   = OrbitConsoleLogic.parseStack(OrbitInspectDecode.string(dict, "stack"))

        var sourceURL    = OrbitInspectDecode.string(dict, "url")
        var sourceLine   = OrbitInspectDecode.integer(dict, "line")
        var sourceColumn = OrbitInspectDecode.integer(dict, "col")
        if sourceURL.isEmpty, let first = frames.first {
            sourceURL = first.url; sourceLine = first.line; sourceColumn = first.column
        }

        let plainText = args.map { $0.plainText }.joined(separator: " ")

        var tableRows: [[String: ConSerializedValue]]? = nil
        if let rowsAny = dict["tableRows"] as? [[String: Any]] {
            tableRows = rowsAny.map { row in
                row.compactMapValues { val -> ConSerializedValue? in
                    guard let d = val as? [String: Any] else { return nil }
                    return ConSerializedValue.decode(d)
                }
            }
        }

        let entry = ConEntry(
            id: "\(pageCounter)_\(OrbitInspectDecode.string(dict, "seq"))",
            level: level,
            args: args,
            stackFrames: frames,
            timestamp: OrbitInspectDecode.number(dict, "ts") ?? 0,
            groupDepth: currentDepth,
            isGroupStart: isStart,
            isGroupEnd: isEnd,
            repeatCount: 1,
            plainText: plainText,
            tableRows: tableRows,
            sourceURL: sourceURL,
            sourceLine: sourceLine,
            sourceColumn: sourceColumn,
            formatString: OrbitInspectDecode.optionalString(dict, "fmt")
        )

        if isStart { groupDepth += 1 }
        else if isEnd { groupDepth = max(0, groupDepth - 1) }
        return entry
    }

    // MARK: Synthetic entries

    public static func navigation(id: String, url: String) -> ConEntry {
        ConEntry(id: id, level: .navigation,
                 args: [.string_("Navigated to \(url)")],
                 stackFrames: [], timestamp: 0, groupDepth: 0,
                 isGroupStart: false, isGroupEnd: false, repeatCount: 1,
                 plainText: "Navigated to \(url)", tableRows: nil,
                 sourceURL: "", sourceLine: 0, sourceColumn: 0, formatString: nil)
    }

    public static func command(id: String, text: String, depth: Int) -> ConEntry {
        ConEntry(id: id, level: .command,
                 args: [.string_(text)],
                 stackFrames: [], timestamp: 0, groupDepth: depth,
                 isGroupStart: false, isGroupEnd: false, repeatCount: 1,
                 plainText: text, tableRows: nil,
                 sourceURL: "", sourceLine: 0, sourceColumn: 0, formatString: nil)
    }

    public static func result(id: String, value: ConSerializedValue, depth: Int) -> ConEntry {
        ConEntry(id: id, level: .result,
                 args: [value],
                 stackFrames: [], timestamp: 0, groupDepth: depth,
                 isGroupStart: false, isGroupEnd: false, repeatCount: 1,
                 plainText: value.plainText, tableRows: nil,
                 sourceURL: "", sourceLine: 0, sourceColumn: 0, formatString: nil)
    }

    public static func errorResult(id: String, message: String, stack: String, depth: Int) -> ConEntry {
        ConEntry(id: id, level: .error,
                 args: [.error_(id: 0, preview: message, stack: stack)],
                 stackFrames: OrbitConsoleLogic.parseStack(stack),
                 timestamp: 0, groupDepth: depth,
                 isGroupStart: false, isGroupEnd: false, repeatCount: 1,
                 plainText: message, tableRows: nil,
                 sourceURL: "", sourceLine: 0, sourceColumn: 0, formatString: nil)
    }

    public var shortSource: String {
        guard !sourceURL.isEmpty else { return "" }
        let noQuery = sourceURL.components(separatedBy: "?").first ?? sourceURL
        let file = noQuery.components(separatedBy: "/").last ?? noQuery
        return sourceLine > 0 ? "\(file):\(sourceLine)" : file
    }
}

// MARK: - Number format helper

public enum ConValueFormat {
    public static func number(_ n: Double) -> String {
        if n.isNaN { return "NaN" }
        if n.isInfinite { return n > 0 ? "Infinity" : "-Infinity" }
        if n == n.rounded() && abs(n) < 1e15 { return String(Int(n)) }
        return String(n)
    }
}

// MARK: - OrbitConsoleLogic

public enum OrbitConsoleLogic {

    // MARK: Format string parsing

    public static func parseFormatString(_ format: String, argCount: Int)
        -> (runs: [ConFormatRun], firstUnusedArg: Int)
    {
        var runs: [ConFormatRun] = []
        var buf = ""
        var argIndex = 0
        var i = format.startIndex

        while i < format.endIndex {
            let c = format[i]
            guard c == "%" else { buf.append(c); i = format.index(after: i); continue }
            let next = format.index(after: i)
            guard next < format.endIndex else { buf.append(c); i = next; continue }
            let spec = format[next]
            switch spec {
            case "s", "d", "i", "f", "o", "O", "c":
                let fspec = ConFormatSpec(rawValue: String(spec)) ?? .string_
                let realIdx = argIndex + 1
                if realIdx < argCount {
                    if !buf.isEmpty { runs.append(.text(buf)); buf = "" }
                    runs.append(.substitution(argIndex: realIdx, spec: fspec))
                    argIndex += 1
                } else {
                    // No argument left for this specifier: it stays literal text, merged into the surrounding run.
                    buf.append("%" + String(spec))
                }
                i = format.index(after: next); continue
            case "%":
                buf.append("%"); i = format.index(after: next); continue
            default:
                buf.append(c); i = format.index(after: i); continue
            }
        }
        if !buf.isEmpty { runs.append(.text(buf)) }
        return (runs, argIndex + 1)
    }

    // MARK: CSS style parsing

    public static func parseCSSStyle(_ css: String) -> ConCSSStyle {
        var s = ConCSSStyle()
        for decl in css.components(separatedBy: ";") {
            let parts = decl.split(separator: ":", maxSplits: 1)
            guard parts.count == 2 else { continue }
            let prop = parts[0].trimmingCharacters(in: .whitespaces).lowercased()
            let val  = parts[1].trimmingCharacters(in: .whitespaces)
            guard !val.isEmpty else { continue }
            switch prop {
            case "color":                            s.color = val
            case "background", "background-color":   s.backgroundColor = val
            case "font-weight":                      s.fontWeight = val
            case "font-size":                        s.fontSize = val
            case "font-style":                       s.fontStyle = val
            case "text-decoration":                  s.textDecoration = val
            default: break
            }
        }
        return s
    }

    // MARK: Stack trace parsing

    public static func parseStack(_ stack: String) -> [ConStackFrame] {
        stack.components(separatedBy: "\n")
            .compactMap { parseFrame($0.trimmingCharacters(in: .whitespaces)) }
    }

    private static func parseFrame(_ line: String) -> ConStackFrame? {
        guard !line.isEmpty else { return nil }
        if line.hasPrefix("at ") { return parseV8Frame(line) }
        return parseWebKitFrame(line)
    }

    private static func parseWebKitFrame(_ line: String) -> ConStackFrame? {
        guard let atRange = line.range(of: "@") else { return nil }
        let fn       = String(line[..<atRange.lowerBound])
        let location = String(line[atRange.upperBound...])
        guard let (url, l, c) = parseLocation(location) else { return nil }
        return ConStackFrame(function: fn, url: url, line: l, column: c)
    }

    private static func parseV8Frame(_ line: String) -> ConStackFrame? {
        var rest = String(line.dropFirst(3))
        if rest.hasSuffix(")"), let open = rest.lastIndex(of: "(") {
            let fn       = String(rest[..<open]).trimmingCharacters(in: .whitespaces)
            let location = String(rest[rest.index(after: open)..<rest.index(before: rest.endIndex)])
            if let (url, l, c) = parseLocation(location) {
                return ConStackFrame(function: fn, url: url, line: l, column: c)
            }
        }
        if let (url, l, c) = parseLocation(rest) {
            return ConStackFrame(function: "", url: url, line: l, column: c)
        }
        return nil
    }

    static func parseLocation(_ location: String) -> (url: String, line: Int, column: Int)? {
        var parts = location.components(separatedBy: ":")
        guard parts.count >= 2 else { return nil }
        var col = 0
        var line = 0
        if let c = Int(parts.last ?? "") { col = c; parts.removeLast() }
        guard let l = Int(parts.last ?? "") else { return nil }
        line = l; parts.removeLast()
        let url = parts.joined(separator: ":")
        guard !url.isEmpty else { return nil }
        return (url, line, col)
    }

    // MARK: Filter query parsing

    public static func parseFilterQuery(_ query: String) -> ConFilterQuery {
        var q = ConFilterQuery()
        let trimmed = query.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty else { return q }

        if trimmed.lowercased().hasPrefix("url:") {
            let pat = String(trimmed.dropFirst(4)).trimmingCharacters(in: .whitespaces)
            q.urlFilter = pat.isEmpty ? nil : pat
            return q
        }

        if trimmed.hasPrefix("-") && trimmed.count > 1 { q.isNegated = true }
        let text = q.isNegated ? String(trimmed.dropFirst()) : trimmed

        if text.hasPrefix("/") && text.hasSuffix("/") && text.count > 2 {
            q.text = String(text.dropFirst().dropLast())
            q.isRegex = true
        } else {
            q.text = text
        }
        return q
    }

    public static func matches(text: String, query: ConFilterQuery) -> Bool {
        if let urlFilter = query.urlFilter {
            return text.localizedCaseInsensitiveContains(urlFilter)
        }
        guard !query.text.isEmpty else { return true }
        let hit: Bool
        if query.isRegex {
            if let re = try? NSRegularExpression(pattern: query.text, options: [.caseInsensitive]) {
                hit = re.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) != nil
            } else {
                hit = false
            }
        } else {
            hit = text.localizedCaseInsensitiveContains(query.text)
        }
        return query.isNegated ? !hit : hit
    }

    // MARK: Repeat-collapse key

    public static func repeatKey(level: ConLevel, plainText: String) -> String? {
        switch level {
        case .navigation, .command, .result, .groupEnd, .clear: return nil
        default: return "\(level.rawValue)|\(plainText)"
        }
    }

    // MARK: Filter chip counts

    public static func levelCounts<Entries: Collection>(of entries: Entries) -> [ConFilterLevel: Int]
        where Entries.Element == ConEntry
    {
        var counts: [ConFilterLevel: Int] = [.all: entries.count]
        for entry in entries {
            for level in ConFilterLevel.allCases where level != .all && level.matches(entry.level) {
                counts[level, default: 0] += 1
            }
        }
        return counts
    }

    // MARK: Input completeness

    public static func isInputComplete(_ js: String) -> Bool {
        guard !js.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
        var depth = 0
        var inString: Character? = nil
        var escape = false
        var templateDepth = 0
        var prevPrev: Character = "\0"
        var prev: Character = "\0"
        var inLineComment = false
        var inBlockComment = false

        for ch in js {
            if escape { escape = false; prevPrev = prev; prev = ch; continue }
            if inLineComment {
                if ch == "\n" { inLineComment = false }
                prevPrev = prev; prev = ch; continue
            }
            if inBlockComment {
                if prev == "*" && ch == "/" { inBlockComment = false }
                prevPrev = prev; prev = ch; continue
            }
            if let q = inString {
                if ch == "\\" { escape = true }
                else if ch == q { inString = nil }
                prevPrev = prev; prev = ch; continue
            }
            switch ch {
            case "\"", "'": inString = ch
            case "`": templateDepth += 1
            case "{", "(", "[": depth += 1
            case "}", ")", "]": depth = max(0, depth - 1)
            case "/":
                if prev == "/" && prevPrev != ":" { inLineComment = true }
            case "*":
                if prev == "/" { inBlockComment = true }
            default: break
            }
            prevPrev = prev; prev = ch
        }
        if depth > 0 || templateDepth > 0 || inString != nil || inBlockComment { return false }
        let t = js.trimmingCharacters(in: .whitespacesAndNewlines)
        let trailingIncomplete = ["&&", "||", "??", "=>", "+", "-", "*", "/", "=", ".", ",", "(", "[", "{"]
        for op in trailingIncomplete where t.hasSuffix(op) { return false }
        return true
    }

    // MARK: Copy all

    /// One line per entry in the same text the per-row "Copy message" produces.
    public static func allMessagesText(_ entries: [ConEntry]) -> String {
        entries.map { $0.args.map { $0.plainText }.joined(separator: " ") }.joined(separator: "\n")
    }

    /// One element of "Copy all as JSON": the page's `JSON.stringify` text for an object, or the message text when there is no object to serialise.
    public enum JSONCopyItem: Equatable, Sendable {
        case json(String)
        case text(String)
    }

    /// Joins the items into one pretty-printed JSON array. A `.json` item that does not parse (the page falls back to `String(o)` for cyclic objects) is embedded as a string so the array stays valid.
    public static func jsonArrayText(_ items: [JSONCopyItem]) -> String {
        guard !items.isEmpty else { return "[]" }
        let elements = items.map { item -> String in
            switch item {
            case .json(let raw):
                let parses = (try? JSONSerialization.jsonObject(with: Data(raw.utf8), options: [.fragmentsAllowed])) != nil
                return parses ? raw : stringLiteral(raw)
            case .text(let text):
                return stringLiteral(text)
            }
        }
        let indented = elements.map { element in
            element.split(separator: "\n", omittingEmptySubsequences: false)
                .map { "  " + $0 }
                .joined(separator: "\n")
        }
        return "[\n" + indented.joined(separator: ",\n") + "\n]"
    }

    private static func stringLiteral(_ text: String) -> String {
        OrbitInspectDecode.jsonLiteral(text) ?? "\"\""
    }

    // MARK: Autocomplete ranking

    public static func rankCompletions(_ completions: [String], prefix: String) -> [String] {
        guard !prefix.isEmpty else { return completions.sorted() }
        let lower = prefix.lowercased()
        return completions
            .filter { $0.lowercased().hasPrefix(lower) }
            .sorted { a, b in
                let aExact = a.hasPrefix(prefix); let bExact = b.hasPrefix(prefix)
                if aExact != bExact { return aExact }
                if a.count != b.count { return a.count < b.count }
                return a < b
            }
    }
}
